CREATE TABLE public.training_attendance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), athlete_id uuid NOT NULL REFERENCES public.athletes(id) ON DELETE CASCADE, training_date date NOT NULL, session text NOT NULL CHECK (session IN ('morning','afternoon','evening')), status text NOT NULL CHECK (status IN ('present','absent','late','excused')), notes text NOT NULL DEFAULT '' CHECK (length(notes)<=500), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,athlete_id,training_date,session));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.training_attendance TO authenticated;
GRANT ALL ON public.training_attendance TO service_role;
ALTER TABLE public.training_attendance ENABLE ROW LEVEL SECURITY;
CREATE POLICY attendance_owner ON public.training_attendance FOR ALL TO authenticated USING (owner_id=auth.uid() AND public.has_role(auth.uid(),'admin')) WITH CHECK (owner_id=auth.uid() AND public.has_role(auth.uid(),'admin'));
CREATE TRIGGER attendance_parent_guard BEFORE INSERT OR UPDATE ON public.training_attendance FOR EACH ROW EXECUTE FUNCTION public.guard_private_row();
CREATE INDEX attendance_owner_date ON public.training_attendance(owner_id,training_date);
CREATE FUNCTION public.save_training_attendance(p_date date,p_session text,p_rows jsonb) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE n integer; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Acceso no autorizado'; END IF; IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Lista inválida'; END IF; INSERT INTO public.training_attendance(owner_id,athlete_id,training_date,session,status,notes) SELECT auth.uid(),r.athlete_id,p_date,p_session,r.status,coalesce(r.notes,'') FROM jsonb_to_recordset(p_rows) AS r(athlete_id uuid,status text,notes text) ON CONFLICT(owner_id,athlete_id,training_date,session) DO UPDATE SET status=excluded.status,notes=excluded.notes,updated_at=now(); GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END; $$;
REVOKE ALL ON FUNCTION public.save_training_attendance(date,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_training_attendance(date,text,jsonb) TO authenticated;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.reset_management_data(text)'::regprocedure) INTO d; d:=replace(d,'DELETE FROM public.athletes', 'DELETE FROM public.training_attendance WHERE owner_id=auth.uid(); DELETE FROM public.athletes'); EXECUTE d; END $$;